	for _, snap := range snapshots {
		el := snap.EffectiveLoad()

		// Gentle load penalty: avoid overloaded instances without hard cutoffs
		if el > 4 {
			loadPenalty := 1.0 / (1.0 + 0.08*float64(el-4))
			scores[snap.ID] *= (0.7 + 0.3*loadPenalty)
		}

		// Cache warmth bonus for sessions (already routed correctly by prefix scorer, just reinforce)
		if req.SessionID != "" && snap.CacheHitRate > 0.3 {
			scores[snap.ID] *= (1.0 + 0.1*snap.CacheHitRate)
		}

		// Memory pressure avoidance - only penalize severe cases
		if snap.KVUtilization > 0.9 {
			scores[snap.ID] *= 0.7
		}
	}

